 47	export const makeCodexOAuthRefreshLock = (
 48	  provider: CodexOAuthRefreshLockProvider
 49	) =>
 50	  Effect.succeed(
 51	    CodexOAuthRefreshLock.of({
 52	      acquire: Effect.fn("CodexOAuthRefreshLock.acquire")(function* (
 53	        input: CodexOAuthRefreshLockAcquireInputType
 54	      ) {
 55	        const subjectHash = yield* codexOAuthProfileSubjectHash(
 56	          input.subject
 57	        ).pipe(
 58	          Effect.mapError(
 59	            (cause) =>
 60	              new CodexOAuthRefreshLockError({
 61	                operation: "acquire",
 62	                reason: "acquisition",
 63	                message: "Unable to derive the Codex OAuth refresh-lock key.",
 64	                cause,
 65	              })
 66	          )
 67	        );
 68	        const owner = yield* Effect.try({
 69	          try: () => Redacted.make(globalThis.crypto.randomUUID()),
 70	          catch: (cause) =>
 71	            new CodexOAuthRefreshLockError({
 72	              operation: "acquire",
 73	              reason: "acquisition",
 74	              subjectHash,
 75	              message: "Unable to create a Codex OAuth refresh-lock owner.",
 76	              cause,
 77	            }),
 78	        });
 79	        const nowEpochMillis = yield* Clock.currentTimeMillis;
 80	        const encodedOwner = yield* Schema.encodeEffect(
 81	          CodexOAuthRefreshLockOwner
 82	        )(owner).pipe(
 83	          Effect.mapError(
 84	            (cause) =>
 85	              new CodexOAuthRefreshLockError({
 86	                operation: "acquire",
 87	                reason: "acquisition",
 88	                subjectHash,
 89	                message: "Unable to encode a Codex OAuth refresh-lock owner.",
 90	                cause,
 91	              })
 92	          )
 93	        );
 94	        const lease = yield* Schema.decodeUnknownEffect(
 95	          CodexOAuthRefreshLockLease
 96	        )({
 97	          subject: input.subject,
 98	          subjectHash,
 99	          owner: encodedOwner,
100	          expiresAtEpochMillis: nowEpochMillis + input.ttlMillis,
101	        }).pipe(
102	          Effect.mapError(
103	            (cause) =>
104	              new CodexOAuthRefreshLockError({
105	                operation: "acquire",
106	                reason: "acquisition",
107	                subjectHash,
108	                message:
109	                  "Unable to construct a Codex OAuth refresh-lock lease.",
110	                cause,
111	              })
112	          )
113	        );
114	        const acquired = yield* provider.acquire(lease, nowEpochMillis);
115	
116	        if (!acquired) {
117	          return yield* new CodexOAuthRefreshLockError({
118	            operation: "acquire",
119	            reason: "contended",
120	            subjectHash,
121	            message: "Codex OAuth refresh is already in progress.",
122	          });
123	        }
