131	
132	        if (lease.expiresAtEpochMillis <= nowEpochMillis) {
133	          return yield* new CodexOAuthRefreshLockError({
134	            operation: "release",
135	            reason: "expired",
136	            subjectHash: lease.subjectHash,
137	            expiresAtEpochMillis: lease.expiresAtEpochMillis,
138	            nowEpochMillis,
