140	          });
141	        }
142	
143	        const released = yield* provider.release(lease);
144	
145	        if (!released) {
146	          return yield* new CodexOAuthRefreshLockError({
147	            operation: "release",
148	            reason: "release",
149	            subjectHash: lease.subjectHash,
150	            message:
151	              "Codex OAuth refresh-lock lease is not owned by this invocation.",
152	          });
153	        }
154	
155	        return yield* Effect.void;
156	      }),
157	    })
158	  );
