160	export const withCodexOAuthRefreshLock = Effect.fn(
161	  "CodexOAuthRefreshLock.withLock"
162	)(function* <A, E, R>(
163	  input: CodexOAuthRefreshLockAcquireInputType,
164	  effect: Effect.Effect<A, E, R>
165	) {
166	  const lock = yield* CodexOAuthRefreshLock;
167	
168	  return yield* Effect.acquireUseRelease(
169	    lock.acquire(input),
170	    () => effect,
171	    (lease) => lock.release(lease)
172	  );
173	});
